import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"39、【蹇】 艮下坎上","description":"周易口訣義 - 39、【蹇】 艮下坎上","frontmatter":{"title":"39、【蹇】 艮下坎上","description":"周易口訣義 - 39、【蹇】 艮下坎上"},"headers":[],"relativePath":"classics/koujueyi/041.md","filePath":"classics/koujueyi/041.md"}'),r={name:"classics/koujueyi/041.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_39、【蹇】-艮下坎上" tabindex="-1">39、【蹇】 艮下坎上 <a class="header-anchor" href="#_39、【蹇】-艮下坎上" aria-label="Permalink to “39、【蹇】 艮下坎上”">​</a></h1><p>彖曰：「蹇」，難也，險在前也。見險而能止，知矣哉！「蹇利西南」，往得中也；「不利東北」，其道窮也。「利見大人」，往有功也。當位「貞吉」，以正邦也。「蹇」之時用大矣哉！</p><p>象曰：山上有水，「蹇」。君子以反身修德。</p><p>初六：往蹇來譽。</p><p>象曰：「往蹇來譽」，宜待也。</p><p>六二：王臣蹇蹇，匪躬之故。</p><p>象曰：「王臣蹇蹇」，終無尤也。</p><p>九三：往蹇來反。</p><p>象曰：「往蹇來反」，內喜之也。</p><p>六四：往蹇來連。象曰：「往蹇來連」，當位實也。</p><p>九五：大蹇朋來。</p><p>象曰：「大蹇朋來」，以中節也。</p><p>上六：往蹇來碩，吉。利見大人。</p><p>象曰：「往蹇來碩」，志在內也。「利見大人」，以從貴也。</p><p>無（四庫全書標明，摘錄時缺豫、隨、無妄、大壯、晉、睽、蹇、解、中孚八卦）</p>',15)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
